  auto disk=readText(manager.root/L"state.json");result=run(BrowserIntegrationDraft{base,base});check(result.unchanged&&!result.saved&&readText(manager.root/L"state.json")==disk,"An unchanged effective draft does not insert defaults or write the catalog");
