  for(auto it=choices.begin();it!=choices.end();++it){auto before=manager.snapshot()["Settings"];base=browserIntegrationSnapshot(before);edited=base;edited[it.key()]=it->is_boolean()?Json(!base[it.key()].get<bool>()):*it;result=run(BrowserIntegrationDraft{base,edited});auto expected=before;expected[it.key()]=edited[it.key()];check(result.saved&&result.settings==expected,"Each scalar browser preference merges only its owned field");}
  const auto stable=manager.snapshot();disk=readText(manager.root/L"state.json");base=browserIntegrationSnapshot(stable["Settings"]);
  for(const auto& invalid:std::vector<Json>{{{"UserAgent","Forbidden"}},{{"BrowserCaptureEnabled",1}},{{"CaptureExcludedUrls",12}},{{"VideoPanelMenuWidth",300.5}},{{"VideoPanelReset",-1}},{{"VideoPanelReset",1.5}},{{"CaptureForceKey","Alt+Del"}},{{"VideoPanelMinKb",{{"unknown",1}}}}}){edited=base;for(auto it=invalid.begin();it!=invalid.end();++it)edited[it.key()]=it->is_boolean()?Json(!base[it.key()].get<bool>()):*it;result=run(BrowserIntegrationDraft{base,edited});check(!result.saved&&!result.error.empty()&&manager.snapshot()==stable&&readText(manager.root/L"state.json")==disk&&!manager.fileInfoDecisionPending,"Invalid or foreign edits release acceptance without changing memory or disk");}
  edited=base;edited.erase("UserAgent");result=run(BrowserIntegrationDraft{base,edited});check(!result.saved&&!result.error.empty(),"Removing an unrelated preference is rejected");
